  if(a==='duration'){modal.duration=Number(target.dataset.duration);renderModal();return;}if(a==='start-water'){startWater();return;}if(a==='device'){open('device');return;}if(a==='device-mode'){if(state.device.status!=='idle')return;state.device.mode=target.dataset.mode;render();renderModal();return;}if(a==='stop-water'||a==='stop-timeout'){stopWater(a==='stop-timeout');return;}
